package com.campuslibrary.model;

import java.time.LocalDateTime;

/** Model (generated by scripts/gen_models.py). Plain JavaBean so it can be read from JSP/EL. */
public class User {
    private long id;
    private String name;
    private String email;
    private String passwordHash;
    private boolean admin;
    private LocalDateTime createdAt;
    private int activeLoans;

    public long getId() { return id; }
    public void setId(long v) { this.id = v; }
    public String getName() { return name; }
    public void setName(String v) { this.name = v; }
    public String getEmail() { return email; }
    public void setEmail(String v) { this.email = v; }
    public String getPasswordHash() { return passwordHash; }
    public void setPasswordHash(String v) { this.passwordHash = v; }
    public boolean isAdmin() { return admin; }
    public void setAdmin(boolean v) { this.admin = v; }
    public LocalDateTime getCreatedAt() { return createdAt; }
    public void setCreatedAt(LocalDateTime v) { this.createdAt = v; }
    public int getActiveLoans() { return activeLoans; }
    public void setActiveLoans(int v) { this.activeLoans = v; }

    public String getInitials() {
        String[] p = name.trim().split("\\s+");
        String s = p[0].substring(0, 1) + (p.length > 1 ? p[p.length - 1].substring(0, 1) : "");
        return s.toUpperCase();
    }
    public String getFirstName() { return name.trim().split("\\s+")[0]; }
    public String getRole() { return admin ? "Librarian" : "Member"; }
}
